# Kernel source for elementwise multiplication (float* and bool*)
elementwise_mul_kernel_source = """
__global__ void elementwise_mul_kernel(const float* a, const bool* m, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        out[idx] = a[idx] * (m[idx] ? 1.0f : 0.0f);
    }
}
"""

